b64_image = ""

img_data = base64.b64decode(b64_image)

try:
    pil_available = True
except Exception:
    pil_available = False

root = tk.Tk()
root.configure(bg="black")
root.attributes("-fullscreen", True)

if pil_available: #tbh idk what archeic stuff chromebook runs on so imma try two and if both fail so be it lmao
    bio = io.BytesIO(img_data)
    img = Image.open(bio).convert("RGBA")
    root.update()
    sw, sh = root.winfo_screenwidth(), root.winfo_screenheight()
    img = img.resize((sw, sh), Image.LANCZOS)
    tk_img = ImageTk.PhotoImage(img)
    lbl = tk.Label(root, image=tk_img, bg="black")
    lbl.pack(expand=True, fill="both")
else:
    try:
        tk_img = tk.PhotoImage(data=base64.b64encode(img_data).decode("ascii"))
        lbl = tk.Label(root, image=tk_img, bg="black")
        lbl.pack(expand=True, fill="both")
    except Exception: #worst come to worst js fulscreen the png lmao
        tf = tempfile.NamedTemporaryFile(delete=False, suffix=".png")
        tf.write(img_data); tf.close()
        subprocess.Popen(["xdg-open", tf.name])

root.mainloop()
